# Adds Size.order and fills a sensible starting order (XS, S, M, L, XL, 2XL ...)
# so existing sizes show in garment order straight away. Admin can change it later.

from django.db import migrations, models

STARTING_ORDER = ['XXS', '2XS', 'XS', 'S', 'SMALL', 'M', 'MEDIUM', 'L', 'LARGE', 'XL', 'XXL', '2XL', 'XXXL', '3XL',
                  '4XL', '5XL', '6XL', 'OS', 'ONE SIZE']


def fill_order(apps, schema_editor):
    Size = apps.get_model('shop', 'Size')
    def key(s):
        n = (s.Size_name or '').strip().upper()
        return (STARTING_ORDER.index(n) if n in STARTING_ORDER else len(STARTING_ORDER), s.id)
    for position, size in enumerate(sorted(Size.objects.all(), key=key), start=1):
        Size.objects.filter(pk=size.pk).update(order=position * 10)  # gaps of 10 = easy to slot new sizes in


